INSERT INTO sys_api(title,path,method,api_group,created_at,updated_at,created_by) SELECT v.title,v.path,v.method,'国标通道收藏',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 FROM (VALUES ('查询通道收藏组','/api/gb28181/channel-favorite-groups','GET'),('新建通道收藏组','/api/gb28181/channel-favorite-groups','POST'),('追加通道收藏','/api/gb28181/channel-favorite-groups/:id/channels','POST'),('移除通道收藏','/api/gb28181/channel-favorite-groups/:id/channels','DELETE'),('删除通道收藏组','/api/gb28181/channel-favorite-groups/:id','DELETE')) v(title,path,method) WHERE NOT EXISTS (SELECT 1 FROM sys_api a WHERE a.path=v.path AND a.method=v.method AND a.deleted_at IS NULL);
INSERT INTO sys_menu(parent_id,path,name,component,title,hide,disable,sort,type,permission,icon,created_at,updated_at,created_by) SELECT 0,'','GbChannelFavoriteManage','','通道收藏管理',1,0,1,3,'gb28181:channel-favorite:manage','',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE permission='gb28181:channel-favorite:manage' AND deleted_at IS NULL);
INSERT INTO sys_role_menu(role_id,menu_id) SELECT 1,id FROM sys_menu WHERE permission='gb28181:channel-favorite:manage' AND NOT EXISTS (SELECT 1 FROM sys_role_menu x WHERE x.role_id=1 AND x.menu_id=sys_menu.id);
INSERT INTO sys_menu_api(menu_id,api_id) SELECT m.id,a.id FROM sys_menu m JOIN sys_api a ON a.path LIKE '/api/gb28181/channel-favorite-groups%' WHERE m.permission='gb28181:channel-favorite:manage' AND a.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM sys_menu_api x WHERE x.menu_id=m.id AND x.api_id=a.id);
INSERT INTO sys_casbin_rule(ptype,v0,v1,v2,v3,v4,v5) SELECT 'p','role_'||rm.role_id,a.path,a.method,'*','','' FROM sys_role_menu rm JOIN sys_menu m ON m.id=rm.menu_id JOIN sys_menu_api ma ON ma.menu_id=m.id JOIN sys_api a ON a.id=ma.api_id WHERE m.permission='gb28181:channel-favorite:manage' AND NOT EXISTS (SELECT 1 FROM sys_casbin_rule c WHERE c.ptype='p' AND c.v0='role_'||rm.role_id AND c.v1=a.path AND c.v2=a.method AND c.v3='*');
